types.verbatim:
/**
 * @brief       POSIX terminal attributes structure.
 * @details     The complete definition is provided by @p <termios.h>.
 */
struct termios;

/**
 * @brief       Terminal window size structure.
 * @details     The complete definition is provided by @p <sys/ioctl.h>.
 */
struct winsize;

method.details:
Attribute changes are performed according to
              @p action. Implementations must apply the complete structure
              atomically with respect to input processing.
